# Generated by build.py from recipe.yml for recipe http-keep-passwords-out-of-the-process-list. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'accounts.txt'), "#carol:retired`nalice:s3cret`n`nbob:hunter2`n")
[IO.File]::WriteAllText((Join-Path $PWD 'broken.txt'), "alice:s3cret`nbob`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--user-file', 'accounts.txt', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --digest -u alice:s3cret http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
